const $=id=>document.getElementById(id);
const START='2026-11-02', ZONE='America/Santiago', STORE='entre-lineas-v1';
function dayKey(d=new Date()){return new Intl.DateTimeFormat('en-CA',{timeZone:ZONE,year:'numeric',month:'2-digit',day:'2-digit'}).format(d)}
function offset(key){return Math.round((Date.parse(key+'T12:00:00Z')-Date.parse(START+'T12:00:00Z'))/86400000)}
function dateFor(i){return new Date(Date.parse(START+'T12:00:00Z')+i*86400000)}
function shortDate(i){return new Intl.DateTimeFormat('es-CL',{timeZone:ZONE,day:'numeric',month:'long'}).format(dateFor(i))}
const LEVELS={suave:{name:'Suave',description:'Una lectura amable: definiciones y mecanismos directos.'},intermedio:{name:'Intermedio',description:'Otra vuelta: fragmentos, sustituciones y pistas menos evidentes.'},desafio:{name:'Desafío',description:'Paso a paso: combina operaciones para encontrar la respuesta.'}};
let level='suave',mode='free';
function bank(){return PUZZLE_BANKS[level]}
function gameKey(i,l=level){return l==='suave'?String(i):l+':'+i}
function storedGame(i,l=level){return data.games[gameKey(i,l)]}
let data={games:{},theme:'dark',level:'suave'}, storageOK=true;
try{const saved=JSON.parse(localStorage.getItem(STORE));if(saved&&typeof saved.games==='object'&&saved.games){data.games=saved.games;data.theme=saved.theme==='light'?'light':'dark';level=LEVELS[saved.level]?saved.level:'suave';data.level=level}}catch{storageOK=false}
let today=offset(dayKey()), selected=0, currentDate=dayKey(), cursor=0;
selected=Math.max(0,bank().findIndex((_,i)=>{const g=storedGame(i);return !g||g.status==='playing'}));
function game(i=selected){const key=gameKey(i);let g=data.games[key];if(!g||typeof g!=='object')g=data.games[key]={answer:'',tries:0,hints:0,status:'playing',guesses:[]};g.answer=typeof g.answer==='string'?g.answer:'';g.tries=Number.isInteger(g.tries)?g.tries:0;g.hints=Number.isInteger(g.hints)?Math.min(3,Math.max(0,g.hints)):0;g.guesses=Array.isArray(g.guesses)?g.guesses:[];return g}
function save(){try{localStorage.setItem(STORE,JSON.stringify(data))}catch{storageOK=false;$('message').textContent='No se pudo guardar: esta partida seguirá disponible mientras mantengas abierta la página.'}}
function normalize(s){return s.toUpperCase().replace(/[ÁÀÄÂ]/g,'A').replace(/[ÉÈËÊ]/g,'E').replace(/[ÍÌÏÎ]/g,'I').replace(/[ÓÒÖÔ]/g,'O').replace(/[ÚÙÜÛ]/g,'U').replace(/[^A-ZÑ]/g,'').slice(0,5)}
function tiles(){const g=game(),value=g.status==='playing'?g.answer:bank()[selected][0];$('tiles').replaceChildren(...Array.from({length:5},(_,i)=>{const e=document.createElement('span');e.className='tile'+(g.status!=='playing'?' solved':i===Math.min(cursor,4)?' current':'');e.textContent=value[i]||'';return e}));}
function hintText(){const g=game(),p=bank()[selected];return [p[2],p[3],'La primera letra es '+p[0][0]+'.'].slice(0,g.hints)}
function render(){renderSelectors();const g=game(),p=bank()[selected],done=g.status!=='playing';$('puzzle-title').textContent=mode==='free'?'A tu ritmo':selected===today?'El críptico de hoy':'Del archivo';$('date').textContent=mode==='free'?'BIBLIOTECA · '+LEVELS[level].name:shortDate(selected);$('number').textContent='EDICIÓN '+String(selected+1).padStart(3,'0');$('difficulty').textContent=LEVELS[level].name.toUpperCase()+' · CINCO LETRAS';$('clue').textContent=p[1];$('answer').value=g.answer;$('answer').disabled=done;$('check').disabled=done;$('hint').disabled=done||g.hints>=3;$('giveup').disabled=done;$('attempts').textContent=g.tries+' intento'+(g.tries===1?'':'s');$('keyboard').querySelectorAll('button').forEach(b=>b.disabled=done);$('hint-box').hidden=!g.hints;$('hint-box').replaceChildren(...hintText().map((t,i)=>{const e=document.createElement('p');e.textContent=(i+1)+'. '+t;return e}));$('result').hidden=!done;$('result').replaceChildren();if(done){const title=document.createElement('h3');title.textContent=g.status==='won'?'Ese era el «¡ajá!» · '+p[0]:'Una nueva forma de verlo · '+p[0];const exp=document.createElement('p');exp.textContent=p[4];const share=document.createElement('button');share.className='secondary';share.textContent='Compartir resultado';share.onclick=shareResult;$('result').append(title,exp,share);$('message').textContent=g.status==='won'?'Bien visto. Puedes seguir con otro cuando quieras.':'A veces, leer la solución también es aprender.'}else{$('message').textContent=storageOK?'Sin prisa. Las buenas ideas se toman su tiempo.':'Tu navegador no permite guardar el progreso.'}tiles();$('next').textContent=today>=bank().length?'Sin sugerencia nueva · sigue en modo libre':'Sugerencia a las 00:00 · modo libre sin límite diario';}
function select(i){selected=i;cursor=game().answer.length;close();render();}
function syncInput(){let g=game();g.answer=normalize($('answer').value);cursor=g.answer.length;$('answer').value=g.answer;save();tiles()}
$('answer').addEventListener('input',syncInput);
$('answer').addEventListener('click',()=>{cursor=$('answer').selectionStart;tiles()});
$('answer').addEventListener('keyup',()=>{cursor=$('answer').selectionStart;tiles()});
$('answer-form').onsubmit=e=>{e.preventDefault();const g=game();if(g.status!=='playing')return;if(g.answer.length!==5){$('message').textContent='Completa las cinco letras antes de comprobar.';$('answer').focus();return}if(g.guesses.includes(g.answer)){$('message').textContent='Ya probaste esa palabra. Busca otra lectura de la frase.';return}g.tries++;g.guesses.push(g.answer);if(g.answer===bank()[selected][0])g.status='won';save();render();if(g.status==='playing'){$('message').textContent='Todavía no. Prueba otra lectura; tienes intentos ilimitados.';$('answer').focus();$('answer').select()}};
['QWERTYUIOP','ASDFGHJKLÑ','ZXCVBNM⌫'].forEach(row=>{const el=document.createElement('div');el.className='keyrow';[...row].forEach(letter=>{const b=document.createElement('button');b.className='key'+(letter==='⌫'?' back':'');b.textContent=letter;b.setAttribute('aria-label',letter==='⌫'?'Borrar letra':letter);b.onclick=()=>{if(game().status!=='playing')return;const input=$('answer');let start=input.selectionStart??input.value.length,end=input.selectionEnd??start;if(letter==='⌫'){if(start===end&&start>0)start--;input.setRangeText('',start,end,'end')}else{input.setRangeText(letter,start,end,'end')}const pos=input.selectionStart;game().answer=normalize(input.value);input.value=game().answer;cursor=Math.min(pos,5);input.setSelectionRange(cursor,cursor);save();tiles()};el.append(b)});$('keyboard').append(el)});
function open(html){$('modal-content').innerHTML=html;if(!$('modal').open)$('modal').showModal()}
function close(){$('modal').close()}
$('close').onclick=close;$('modal').onclick=e=>{if(e.target===$('modal')){const r=$('modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}};
$('hint').onclick=()=>{const g=game();if(g.status!=='playing'||g.hints>=3)return;g.hints++;save();render();};
$('giveup').onclick=()=>{open('<h2>¿Ver la solución?</h2><p>Esta edición quedará como revelada y no contará como resuelta. Puedes seguir probando sin límite.</p><button class="secondary" id="keep">Seguir pensando</button><button class="secondary" id="reveal">Sí, ver la solución</button>');$('keep').onclick=close;$('reveal').onclick=()=>{game().status='givenup';save();close();render()}};
$('today').onclick=()=>{mode='daily';today=offset(dayKey());if(today<0||today>=bank().length){open('<h2>Un archivo para seguir descubriendo</h2><p>Esta primera colección diaria cubre del 2 de noviembre al 1 de diciembre de 2026, con tres niveles. No hay una sugerencia diaria programada para hoy. El modo libre permite seguir con toda la biblioteca.</p>');return}select(today)};
$('archive').onclick=()=>{mode='daily';render();open('<h2>Pequeños descubrimientos</h2><p>Vuelve a una edición anterior. Cada partida conserva sus propias pistas e intentos.</p><div class="archive-list" id="archive-list"></div>');for(let i=Math.min(today,bank().length-1);i>=0;i--){const b=document.createElement('button');b.className='archive-item';const s=storedGame(i)?.status;b.textContent=String(i+1).padStart(3,'0')+' · '+shortDate(i)+'  '+(s==='won'?'✓ Resuelto':s==='givenup'?'↗ Revelado':i===today?'Hoy · Jugar':'Jugar');b.onclick=()=>select(i);$('archive-list').append(b)}};
function statistics(){let streak=0;let day=storedGame(today)?.status==='won'?today:today-1;while(day>=0&&storedGame(day)?.status==='won'){streak++;day--}const entries=bank().map((_,i)=>[i,storedGame(i)]).filter(([,g])=>g);const played=entries.filter(([,g])=>g.tries>0||g.hints>0||g.status!=='playing'),won=entries.filter(([,g])=>g.status==='won');return {played:played.length,won:won.length,streak,pending:bank().length-entries.filter(([,g])=>g.status==='won'||g.status==='givenup').length,assisted:won.filter(([,g])=>g.hints>0).length}}
$('stats').onclick=()=>{const s=statistics();open('<h2>Tu rincón · '+LEVELS[level].name+'</h2><div class="stat-grid"><div><b>'+s.played+'</b>iniciados</div><div><b>'+s.won+'</b>resueltos</div><div><b>'+s.pending+'</b>pendientes</div><div><b>'+s.streak+'</b>días de racha</div></div><p>'+s.assisted+' resueltos con ayuda. Las estadísticas corresponden al nivel seleccionado. La racha cuenta sugerencias de fechas consecutivas resueltas, hasta hoy o ayer; las pistas no la cortan. Cada acertijo conserva un único progreso, tanto si lo juegas como sugerencia diaria como en modo libre.</p><p>Todo se guarda solo en este navegador y dispositivo. Sin cuentas, anuncios ni seguimiento. Borrar los datos del navegador elimina tu historial.</p>')};
$('help').onclick=()=>open('<h2>Dos caminos. Una palabra.</h2><p>Un críptico combina una <strong>definición</strong> con un <strong>juego de palabras</strong>. Ambas partes llevan a la misma respuesta.</p><p><strong>Ejemplo de práctica:</strong> «Saco, revuelto, trae desorden (4)». La definición es «desorden»; «revuelto» pide reorganizar SACO. La respuesta es CAOS.</p><ol><li>Lee la frase buscando una definición al principio o al final.</li><li>Busca señales: «revuelto» puede indicar un anagrama; «en» puede esconder una palabra; otras pistas juegan con fragmentos o dos significados.</li><li>Escribe cinco letras y pulsa Comprobar o Enter. Puedes probar sin límite. Se aceptan tildes al escribir, pero las casillas las omiten; la Ñ se conserva.</li></ol><p>Usa el teclado de pantalla o el de tu equipo. Toca las casillas para editar. Hay tres pistas progresivas y una explicación al terminar.</p><p>Elige Suave, Intermedio o Desafío. La sugerencia diaria cambia a las 00:00 de Santiago, pero no limita tus partidas. En modo libre puedes recorrer los 90 acertijos originales (30 por nivel) y pedir el siguiente pendiente. La biblioteca permite volver a una solución, marcada como resuelta o revelada. Si juegas por adelantado una sugerencia futura, conservará su estado cuando llegue ese día. El calendario inicial cubre del 2 de noviembre al 1 de diciembre de 2026; la biblioteca sigue disponible después.</p>');
function applyTheme(){document.body.classList.toggle('light',data.theme==='light');$('theme').textContent=data.theme==='light'?'☾':'☼';$('theme').setAttribute('aria-label',data.theme==='light'?'Activar tema oscuro':'Activar tema claro');document.querySelector('meta[name="theme-color"]').content=data.theme==='light'?'#f7f4ec':'#121313'}
$('theme').onclick=()=>{data.theme=data.theme==='light'?'dark':'light';save();applyTheme()};
async function shareResult(){const g=game();const text='Entre líneas · '+LEVELS[level].name+' · '+(mode==='free'?'Acertijo '+(selected+1):shortDate(selected))+'\n'+(g.status==='won'?'✳ Resuelto en '+g.tries+' intento'+(g.tries===1?'':'s'):'↗ Solución descubierta')+' · '+g.hints+' pista'+(g.hints===1?'':'s')+'\nUn pequeño ritual para Paula.';try{if(navigator.share){await navigator.share({title:'Entre líneas',text})}else if(navigator.clipboard){await navigator.clipboard.writeText(text);$('message').textContent='Resultado copiado, sin revelar la respuesta.'}else throw Error()}catch(e){if(e.name!=='AbortError'){open('<h2>Tu resultado</h2><p id="share-text"></p>');$('share-text').textContent=text}}}
setInterval(()=>{const key=dayKey();if(key!==currentDate){const wasToday=mode==='daily'&&selected===today;currentDate=key;today=offset(key);if(wasToday&&today>=0&&today<bank().length)select(today);else render()}},15000);
window.addEventListener('storage',e=>{if(e.key===STORE&&e.newValue){try{const newer=JSON.parse(e.newValue);if(newer&&typeof newer.games==='object'&&newer.games){data=newer;level=LEVELS[data.level]?data.level:'suave';applyTheme();render()}}catch{}}});
function renderSelectors(){for(const l of Object.keys(LEVELS))$('level-'+l).setAttribute('aria-pressed',String(l===level));$('level-description').textContent=LEVELS[level].description;$('daily-mode').setAttribute('aria-pressed',String(mode==='daily'));$('free-mode').setAttribute('aria-pressed',String(mode==='free'));$('free-controls').hidden=mode!=='free';const pending=bank().filter((_,i)=>{const g=storedGame(i);return !g||g.status==='playing'}).length;$('library-count').textContent=pending+' pendientes de '+bank().length+' · '+LEVELS[level].name;$('next-puzzle').disabled=pending===0;$('next-puzzle').textContent=pending?'Siguiente pendiente →':'Nivel completado ✓'}
function nextPending(){for(let n=1;n<=bank().length;n++){const i=(selected+n)%bank().length;const g=storedGame(i);if(!g||g.status==='playing'){select(i);return}}open('<h2>¡Nivel completado!</h2><p>Ya recorriste todos los acertijos de este nivel. Puedes probar otra dificultad o volver a sus explicaciones en la biblioteca.</p>')}
function chooseLevel(l){if(!LEVELS[l])return;level=l;data.level=l;save();cursor=game().answer.length;close();render()}
for(const l of Object.keys(LEVELS))$('level-'+l).onclick=()=>chooseLevel(l);
$('daily-mode').onclick=()=>$('today').click();
$('free-mode').onclick=()=>{mode='free';render();if(game().status!=='playing')nextPending()};
$('next-puzzle').onclick=nextPending;
$('library').onclick=()=>{open('<h2>Biblioteca · '+LEVELS[level].name+'</h2><p>Juega sin límite diario. Los resultados se conservan al cambiar de modo. Para volver a leer una explicación, abre un acertijo terminado.</p><div class="archive-list" id="library-list"></div>');bank().forEach((_,i)=>{const b=document.createElement('button');b.className='archive-item';const g=storedGame(i);b.textContent='Acertijo '+String(i+1).padStart(2,'0')+' · '+(!g||g.status==='playing'?'Pendiente':g.status==='won'?'✓ Resuelto':'↗ Revelado');b.onclick=()=>{mode='free';select(i)};$('library-list').append(b)})};
applyTheme();render();
